// -- Entry-path resolution ------------------------------------------------
// Webhook Trigger -> Verify JWT -> here   (public HTTP; auth enforced)
// Called as Tool  -> here                 (sub-workflow; already trusted)
//
// $('Webhook Trigger') THROWS when that node did not run in this execution --
// it does NOT return undefined, so `?.` and `||` cannot rescue it, and an
// Expression field cannot hold try/catch. That is why this resolution lives
// in a Code node. Removing this try/catch breaks the Called-as-Tool path.
let webhookJson = null;
try {
  webhookJson = $('Webhook Trigger').first().json;
} catch (e) {
  // tool / sub-workflow path -- Webhook Trigger never executed.
}

let src;
if (webhookJson) {
  // 'Verify JWT' runs with onError = continueRegularOutput, so a rejected
  // token arrives here as data instead of failing the execution. Supabase
  // GET /auth/v1/user returns the user object on success; no .id = rejected.
  const auth = $input.first().json || {};
  if (!auth.id) {
    return [{ json: {
      status: 'error',
      errors: ['Unauthorized. A valid Supabase session token is required in the Authorization header.'],
      calculatedAt: new Date().toISOString()
    } }];
  }
  src = webhookJson.body || webhookJson;
} else {
  src = $input.first().json;
}

// -- Inputs ---------------------------------------------------------------
// Below this figure the input is not a vehicle valuation, it is junk.
const MIN_VEHICLE_VALUE_AED = 5000;

const vehicleValue = parseFloat(src.vehicleValue);
const loanPayoffAmount = parseFloat(src.loanPayoffAmount);
// Credit score is entered manually by the rep from the customer's AECB report --
// real-time bureau lookups require a licensed financial-institution agreement in
// the UAE, so this stays a manual field rather than an automated external call.
const creditScore = parseInt(src.creditScore, 10);

// Attribution for the quote record. A finance figure with a lender
// disclaimer must be traceable to a customer and a rep.
const leadEmail = (src.lead_email || src.email || '').toString().trim() || null;
const leadName  = src.lead_name  || src.name  || null;
const quotedBy  = src.quoted_by  || src.rep   || null;

const errors = [];
if (!Number.isFinite(vehicleValue) || vehicleValue < MIN_VEHICLE_VALUE_AED) {
  errors.push('vehicleValue must be a realistic vehicle valuation of at least AED ' + MIN_VEHICLE_VALUE_AED + '.');
}
if (!Number.isFinite(loanPayoffAmount) || loanPayoffAmount < 0) {
  errors.push('loanPayoffAmount must be zero or a positive number (AED).');
}
if (!Number.isFinite(creditScore) || creditScore < 300 || creditScore > 900) {
  errors.push('A valid AECB credit score (300-900) is required. Ask the customer for their latest AECB report.');
}
// A quote with no customer attached cannot be followed up or audited, so this
// is required rather than optional -- an unattached row is as good as no row.
if (!leadEmail) {
  errors.push('lead_email is required so the quote can be attached to a customer.');
} else if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(leadEmail)) {
  errors.push('lead_email is not a valid email address.');
}

if (errors.length) {
  return [{ json: { status: 'error', errors: errors, lead_email: leadEmail,
    lead_name: leadName, calculatedAt: new Date().toISOString() } }];
}

const equity = vehicleValue - loanPayoffAmount;
const ltv = vehicleValue > 0 ? Math.round((loanPayoffAmount / vehicleValue) * 1000) / 10 : null;

let financeTier = 'Subprime';
let indicativeApr = 12.5;
if (creditScore >= 720)      { financeTier = 'Prime Plus'; indicativeApr = 3.99; }
else if (creditScore >= 680) { financeTier = 'Prime';      indicativeApr = 5.49; }
else if (creditScore >= 620) { financeTier = 'Near Prime'; indicativeApr = 7.99; }

return [{
  json: {
    status: 'success',
    equity_aed: Math.round(equity),
    equity_status: equity >= 0 ? 'Positive' : 'Negative',
    loan_to_value_pct: ltv,
    credit_score: creditScore,
    finance_tier: financeTier,
    indicative_apr_pct: indicativeApr,
    vehicle_value_aed: Math.round(vehicleValue),
    loan_payoff_aed: Math.round(loanPayoffAmount),
    disclaimer: 'Indicative only. Final APR and approval are set by the lender, not by NEXUS OS.',
    calculated_at: new Date().toISOString(),
    lead_email: leadEmail,
    lead_name: leadName,
    quoted_by: quotedBy
  }
}];

// Re-emit the calculation. 'Log Quote' returns an empty body
// (Prefer: return=minimal), so without this the webhook would answer with
// nothing. Also keeps the sub-workflow caller contract intact.
return $('Calculate Equity & Tier').all();

